contract InvMutTest {
    C c;
    uint public constant decimals = 18;
    bool public reverted;

    constructor(C _c) {
        c = _c;
    }

    function test_owner_balance_is_totalDistributed() public {
        uint256 balance = c.balanceOf(c.owner());
        uint256 distributed = c.totalDistributed();
        assert(balance == distributed);
    }
}

